import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, vec3 } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, PlaneGeometry, Mesh, Vector3, Euler } = ctx.THREE;

  const group = new Group();
  group.userData.cleanup = () => {
    // Dispose resources
    geometry.dispose();
    material.dispose();
  };

  // Create plane geometry (512x320 px → aspect ratio 1.6:1, scaled to ~1.6 x 1.0 scene units)
  const geometry = new PlaneGeometry(1.6, 1.0, 1, 1);

  // Load brushed metal texture
  const material = new MeshBasicNodeMaterial({
    color: 0xffffff,
    map: null,
  });

  // Async texture load
  ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
    material.map = texture;
    material.needsUpdate = true;
  });

  const mesh = new Mesh(geometry, material);

  // Apply scene position and rotation from config
  if (config.scenePosition) {
    const pos = config.scenePosition;
    mesh.position.set(pos.x || 0, pos.y || 0, pos.z || 0);
    if (pos.rotationXYZ) {
      mesh.rotation.set(pos.rotationXYZ[0] || 0, pos.rotationXYZ[1] || 0, pos.rotationXYZ[2] || 0);
    }
    if (pos.scale) {
      mesh.scale.set(pos.scale[0] || 1, pos.scale[1] || 1, pos.scale[2] || 1);
    }
  }

  // Ensure mesh renders with correct depth
  mesh.renderOrder = 1;

  group.add(mesh);

  return group;
}
